fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 length mismatch");
    assert_eq!(conds_1.len(), n, "conds_1 length mismatch");
    assert_eq!(conds_2.len(), n, "conds_2 length mismatch");

    // Ensure `avgs` has exactly the needed length; caller allows overwrite.
    avgs.resize(n, 0);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // Problem statement guarantees at least one is true, but keep a defensive check.
        assert!(c1 || c2, "Both conditions are false at index {}", i);

        let v1 = vals_1[i];
        let v2 = vals_2[i];

        avgs[i] = match (c1, c2) {
            (true, true) => (v1 + v2) / 2, // safe under given bounds (< 1000 each)
            (true, false) => v1,
            (false, true) => v2,
            (false, false) => unreachable!(),
        };
    }
}